// Responsive image lookup. Generated by scripts/optimize-images.mjs from the
// masters in source-files/; do not edit image-manifest.json by hand.
import manifest from './image-manifest.json';

export interface ImageInfo {
  folder: string;
  widths: number[];
  /** Intrinsic size of the largest derivative, for width/height attributes. */
  width: number;
  height: number;
}

const images: Record<string, ImageInfo> = manifest;

export const imageInfo = (name: string): ImageInfo => {
  const info = images[name];
  if (!info)
    throw new Error(
      `Unknown image "${name}" — add a master to source-files/ and run npm run images:optimize`,
    );
  return info;
};
export const imageWidths = (name: string): number[] => imageInfo(name).widths;
export const imageSrc = (name: string, width: number): string =>
  `/images/${imageInfo(name).folder}/${name}-${width}.webp`;
/** Largest derivative (at most 1600px wide) — never the full-size master. */
export const largestImage = (name: string): string => {
  const { widths } = imageInfo(name);
  return imageSrc(name, widths[widths.length - 1]);
};
/** A derivative close to the requested width, e.g. for video posters. */
export const imageNear = (name: string, target: number): string => {
  const { widths } = imageInfo(name);
  return imageSrc(
    name,
    widths.find((w) => w >= target) ?? widths[widths.length - 1],
  );
};
